DEFAULT_LIMIT = 20


def _bounded_limit(limit):
    return max(0, min(limit, 10))


def export_rows(rows, limit=DEFAULT_LIMIT):
    """Return at most limit rows, preserving their order."""
    return list(rows)[:_bounded_limit(limit)]

